param([string]$Source=(Join-Path $PSScriptRoot '../live-management/windows-dns-credential-recovery.ps1'),[string]$TestParent=(Join-Path (Split-Path $PSScriptRoot -Parent) '.local/manager-installation'))
$ErrorActionPreference='Stop'
if(!([Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Run Windows recovery acceptance using the authorized Domain02 administrative session'}
$errors=$null;$sourceAst=[Management.Automation.Language.Parser]::ParseFile($Source,[ref]$null,[ref]$errors);if($errors.Count){throw 'Windows recovery source does not parse'}
. $Source
$testRoot=Join-Path $TestParent ('windows-credential-tests-'+[Guid]::NewGuid().ToString());New-Item -ItemType Directory -Path $testRoot | Out-Null
& icacls $testRoot /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null;if($LASTEXITCODE -ne 0){throw 'Fixture ACL installation failed'}
$script:actualWrites=0;$writerAst=$sourceAst.Find({param($node);$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq 'Write-DnsRecoveryFile'},$true)
Invoke-Expression ($writerAst.Extent.Text.Replace('function Write-DnsRecoveryFile','function Write-OriginalDnsRecoveryFile'))
function Write-DnsRecoveryFile([string]$Path,[byte[]]$Bytes){if([IO.Path]::GetFileName($Path) -eq 'kubeconfig.json'){$script:actualWrites++};Write-OriginalDnsRecoveryFile $Path $Bytes}
function Assert($condition,[string]$message){if(!$condition){throw $message}}
function Reject([scriptblock]$operation,[string]$name){$denied=$false;try{$null=& $operation}catch{$denied=$true};Assert $denied ('Unexpected acceptance: '+$name)}
function New-FixtureKubeconfig([string]$token){return @{apiVersion='v1';kind='Config';clusters=@(@{name='cluster';cluster=@{server='https://10.99.15.50:6443';'tls-server-name'='kubernetes.cormierconsulting.io';'certificate-authority-data'='Synthetic-Pinned-CA'}});users=@(@{name='bridge';user=@{token=$token}});contexts=@(@{name='bridge';context=@{cluster='cluster';user='bridge';namespace='dns-system'}});'current-context'='bridge'}|ConvertTo-Json -Depth 10}
function Fixture([switch]$Missing,[switch]$Unchanged){$id=[Guid]::NewGuid().ToString();$directory=Join-Path $testRoot $id;New-Item -ItemType Directory -Path $directory | Out-Null;& icacls $directory /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null;if(!$Missing){[IO.File]::WriteAllText((Join-Path $directory 'kubeconfig.json'),(New-FixtureKubeconfig $(if($Unchanged){'synthetic.restored.signature'}else{'synthetic.before.signature'})),[Text.UTF8Encoding]::new($false))};return @{Root=$directory;Id=$id;TargetJson=(New-FixtureKubeconfig 'synthetic.restored.signature');ClusterCaData='Synthetic-Pinned-CA';AccountUid='fixture-account';AssertQuiescent={$true}}}
$script:lostReadback=$false;$script:rejectCandidate=$false
$authenticate={param($path,$uid);if($script:rejectCandidate){return $false};if($script:lostReadback -and [IO.Path]::GetFileName($path) -eq 'kubeconfig.json'){$script:lostReadback=$false;throw 'Injected readback loss'};$value=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json;return $uid -ceq 'fixture-account' -and $value.users[0].user.token -ceq 'synthetic.restored.signature'}
$checks=@()
try{
 $f=Fixture;$prepared=New-DnsCredentialRecovery @f;$json=$prepared|ConvertTo-Json -Depth 10 -Compress;Assert (!$json.Contains('synthetic.') -and !$json.Contains('token')) 'Receipt leaked credential';$paths=Get-DnsRecoveryPaths $f.Root $f.Id;$encrypted=[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($paths.payload));Assert (!$encrypted.Contains('synthetic.before.signature') -and !$encrypted.Contains('synthetic.restored.signature')) 'Payload contains plaintext';Assert ((Get-DnsRecoveryPayload $paths $f.Id).accountUid -eq 'fixture-account') 'DPAPI roundtrip failed';$prior=New-DnsCredentialRecovery @f;Assert ($prior.id -ceq $prepared.id) 'Preparation not idempotent';$checks+='Encrypted staging and idempotent preparation'
 $start=$script:actualWrites;$applied=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true};Assert ($applied.status -eq 'Applied' -and $script:actualWrites -eq $start+1) 'Atomic replacement failed';$null=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true};Assert ($script:actualWrites -eq $start+1) 'Repeated Apply rewrote credential';Assert (!(Test-Path -LiteralPath $paths.lease)) 'Lease was not released';$checks+='Changed credential applied once with confirmed readback'
 foreach($mode in @('Unchanged','Missing')){$f=if($mode -eq 'Unchanged'){Fixture -Unchanged}else{Fixture -Missing};$null=New-DnsCredentialRecovery @f;$start=$script:actualWrites;$result=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true};Assert ($result.status -eq 'Applied' -and $script:actualWrites -eq $start+$(if($mode -eq 'Missing'){1}else{0})) ($mode+' recovery writes differ')};$checks+='Missing credential restored; unchanged formatting and bytes preserved'
 $f=Fixture -Unchanged;$original=[IO.File]::ReadAllBytes((Join-Path $f.Root 'kubeconfig.json'));$v=$f.TargetJson|ConvertFrom-Json;$f.TargetJson=[ordered]@{'current-context'='bridge';contexts=@([ordered]@{context=[ordered]@{namespace='dns-system';user='bridge';cluster='cluster'};name='bridge'});users=@([ordered]@{user=@{token='synthetic.restored.signature'};name='bridge'});clusters=@([ordered]@{cluster=[ordered]@{'certificate-authority-data'='Synthetic-Pinned-CA';'tls-server-name'='kubernetes.cormierconsulting.io';server='https://10.99.15.50:6443'};name='cluster'});kind='Config';apiVersion='v1';preferences=@{}}|ConvertTo-Json -Depth 12 -Compress;$null=New-DnsCredentialRecovery @f;$start=$script:actualWrites;$result=Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true};Assert ($result.status -eq 'Applied' -and $script:actualWrites -eq $start -and (Test-DnsRecoveryBytes $original ([IO.File]::ReadAllBytes((Join-Path $f.Root 'kubeconfig.json'))))) 'Equivalent reordered JSON changed original bytes';$checks+='JavaScript/PowerShell property order and empty preferences preserve exact original bytes'
 $f=Fixture;$null=New-DnsCredentialRecovery @f;$script:lostReadback=$true;$start=$script:actualWrites;Reject {Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true}} 'lost readback';$result=Repair-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate;Assert ($result.status -eq 'Applied' -and $script:actualWrites -eq $start+1) 'Reconciliation replayed write';$checks+='Accepted file replacement reconciled without replay'
 $f=Fixture;$null=New-DnsCredentialRecovery @f;$start=$script:actualWrites;[IO.File]::WriteAllText((Join-Path $f.Root 'kubeconfig.json'),(New-FixtureKubeconfig 'synthetic.foreign.signature'));Reject {Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true}} 'foreign update';Assert ($script:actualWrites -eq $start) 'Foreign update caused writes';$checks+='Concurrent private credential changes rejected'
 $f=Fixture;$null=New-DnsCredentialRecovery @f;$other=$f.Clone();$other.Id=[Guid]::NewGuid().ToString();Reject {New-DnsCredentialRecovery @other} 'overlapping transaction';$script:rejectCandidate=$true;$start=$script:actualWrites;Reject {Invoke-DnsCredentialRecovery -Root $f.Root -Id $f.Id -Authenticate $authenticate -AssertQuiescent {$true}} 'rejected candidate';Assert ($script:actualWrites -eq $start) 'Rejected authentication caused write';$script:rejectCandidate=$false;$checks+='Active lease blocks overlap; rejected candidate leaves credential unchanged'
 foreach($change in @('endpoint','TLS','CA','exec','identity')){$v=New-FixtureKubeconfig 'synthetic.restored.signature'|ConvertFrom-Json;switch($change){'endpoint'{$v.clusters[0].cluster.server='https://foreign.example:6443'};'TLS'{$v.clusters[0].cluster|Add-Member -NotePropertyName 'insecure-skip-tls-verify' -NotePropertyValue $true};'CA'{$v.clusters[0].cluster.'certificate-authority-data'='Foreign-CA'};'exec'{$v.users[0].user|Add-Member -NotePropertyName exec -NotePropertyValue @{command='foreign'}};'identity'{$v.contexts[0].context.namespace='foreign'}};Reject {Assert-DnsRecoveryConfiguration ($v|ConvertTo-Json -Depth 10) 'Synthetic-Pinned-CA'} $change};$checks+='Foreign endpoints, CA, contexts, TLS bypass and executable credentials rejected'
 $f=Fixture;$f.AssertQuiescent={$false};$start=$script:actualWrites;Reject {New-DnsCredentialRecovery @f} 'active DNS operation';Assert ($script:actualWrites -eq $start) 'Active operations caused writes';Assert (!(Test-Path -LiteralPath (Join-Path $f.Root 'credential-recovery-active.json'))) 'Rejected preparation retained lease';$checks+='Unconfirmed bridge quiescence prevents staging and replacement'
 $report=@{passed=$true;checks=$checks;actualFixtureWrites=$script:actualWrites;productionWrites=0;fixtureRoot=$testRoot;at=[DateTime]::UtcNow.ToString('o')};$report|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $TestParent 'windows-dns-credential-recovery-tests.json');([pscustomobject]$report)|Select-Object passed,checks,actualFixtureWrites,productionWrites|ConvertTo-Json -Depth 10
}finally{
 $resolved=[IO.Path]::GetFullPath($testRoot);$parent=[IO.Path]::GetFullPath($TestParent).TrimEnd('\')+'\';if(!$resolved.StartsWith($parent,[StringComparison]::OrdinalIgnoreCase)){throw 'Fixture cleanup escaped its test directory'};Remove-Item -LiteralPath $resolved -Recurse -Force
}
